      var date = new Date();

      // Campos originais
      var horas = ('0' + date.getHours()).slice(-2);
      var minutos = ('0' + date.getMinutes()).slice(-2);
      var segundos = ('0' + date.getSeconds()).slice(-2);

      var dia = ('0' + date.getDate()).slice(-2);
      var mes = ('0' + (date.getMonth() + 1)).slice(-2);
      var ano = date.getFullYear();

      // Formatando data e horário
      var horario = horas + ':' + minutos;              
      var horarioCompleto = horas + ':' + minutos + ':' + segundos;
      var dataHoje1 = dia + '/' + mes + '/' + ano;
      var dataHoje2 = ano + '-' + mes + '-' + dia;

      // Timeout em segundos
      var timeout = 900; 

      // Criamos uma nova data apenas para adicionar tempo
      var dataComTimeout = new Date(date);
      dataComTimeout.setSeconds(dataComTimeout.getSeconds() + timeout);

      // Criamos uma nova data apenas para remover tempo
      var dataComTimeoutNegativo = new Date(date);
      dataComTimeoutNegativo.setSeconds(dataComTimeoutNegativo.getSeconds() - timeout);

      // Formatando a hora "somada"
      var horaAdd = ('0' + dataComTimeout.getHours()).slice(-2);
      var minutoAdd = ('0' + dataComTimeout.getMinutes()).slice(-2);
      var segundoAdd = ('0' + dataComTimeout.getSeconds()).slice(-2);
      var horaAddTime = horaAdd + ':' + minutoAdd + ':' + segundoAdd;

      // Formatando a hora "subtraída"
      var horaRemove = ('0' + dataComTimeoutNegativo.getHours()).slice(-2);
      var minutoRemove = ('0' + dataComTimeoutNegativo.getMinutes()).slice(-2);
