const cep = $('CEP').item.json.body.query.cep;

// URL da API do ViaCEP
const apiUrl = `https://viacep.com.br/ws/${cep}/json/`;

async function consultarCEP(cep) {
    try {
        // Fazendo requisição HTTP com `this.helpers.request`
        const response = await this.helpers.httpRequest({
            method: 'GET',
            url: apiUrl,
            json: true,
        });

        // Verifica se a resposta contém erro
        if (response && !response.erro) {
            return {
                cep: cep,
                endereco: response,
            };
        } else {
            return {
                cep: cep,
                mensagem: "Não encontrado",
            };
        }
    } catch (error) {
        return {
            cep: cep,
            erro: "Erro ao consultar o CEP",
            detalhes: error.message,
        };
    }
}

// Executa a consulta e retorna o resultado
return consultarCEP(cep).then(result => ({ json: result }));

const cpf = $('CPF').item.json.body.query.cpf;

function validarCPF(cpf) {
    // Verifica se o CPF tem o tamanho correto e não é uma sequência repetida
    if (cpf.length !== 11 || 
        cpf === "00000000000" || 
        cpf === "11111111111" || 
        cpf === "22222222222" || 
        cpf === "33333333333" || 
        cpf === "44444444444" || 
        cpf === "55555555555" || 
        cpf === "66666666666" || 
        cpf === "77777777777" || 
        cpf === "88888888888" || 
        cpf === "99999999999") {
        return "inválido";
    }

    let add = 0;

    // Calcula o primeiro dígito verificador
    for (let i = 0; i < 9; i++) {
        add += parseInt(cpf.charAt(i)) * (10 - i);
    }
    let rev = 11 - (add % 11);
    if (rev === 10 || rev === 11) rev = 0;
    if (rev !== parseInt(cpf.charAt(9))) return "inválido";

    add = 0;

    // Calcula o segundo dígito verificador
    for (let i = 0; i < 10; i++) {
        add += parseInt(cpf.charAt(i)) * (11 - i);
    }
    rev = 11 - (add % 11);
    if (rev === 10 || rev === 11) rev = 0;
    if (rev !== parseInt(cpf.charAt(10))) return "inválido";

    return "válido";
}

const resultado = validarCPF(cpf);
return { json: { cpf, resultado } };

