// Função para verificar se uma string está no formato esperado
function isValidDateTime(dateTimeString) {
    const regex = /^\d{2}\/\d{2}\/\d{4} \d{2}:\d{2}:\d{2}$/; // Formato DD/MM/YYYY HH:mm:ss
    return regex.test(dateTimeString);
}

// Verificar se as datas são válidas
if (!FollowContato || !isValidDateTime(FollowContato)) {
    throw new Error('FollowContato está ausente ou em um formato inválido.');
}
if (!FollowEu || !isValidDateTime(FollowEu)) {
    throw new Error('FollowEu está ausente ou em um formato inválido.');
}

// Função para converter string no formato DD/MM/YYYY HH:mm:ss para objeto Date
function parseDateTime(dateTimeString) {
    const [datePart, timePart] = dateTimeString.split(' '); // Separar data e hora
    const [day, month, year] = datePart.split('/').map(Number); // Separar dia, mês e ano
    const [hours, minutes, seconds] = timePart.split(':').map(Number); // Separar hora, minutos e segundos
    return new Date(year, month - 1, day, hours, minutes, seconds); // Criar objeto Date
}

try {
    // Converter as datas para objetos Date
    const date1 = parseDateTime(FollowContato);
    const date2 = parseDateTime(FollowEu);

    // Calcular a diferença em milissegundos
    const diffMs = date2 - date1;

    // Verificar se a diferença é positiva ou negativa
    const isFuture = diffMs >= 0;

    // Calcular dias, horas, minutos e segundos
    const diffDays = Math.floor(Math.abs(diffMs) / (1000 * 60 * 60 * 24)); // Total de dias inteiros
    const diffHours = Math.floor((Math.abs(diffMs) % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)); // Horas restantes
    const diffMinutes = Math.floor((Math.abs(diffMs) % (1000 * 60 * 60)) / (1000 * 60)); // Minutos restantes
    const diffSeconds = Math.floor((Math.abs(diffMs) % (1000 * 60)) / 1000); // Segundos restantes

    // Calcular o total de horas (incluindo dias)
    const totalHours = Math.floor(Math.abs(diffMs) / (1000 * 60 * 60)); // Total de horas inteiras

    // Criar um número no formato HHMMSS para facilitar cálculos posteriores
    const totalHorasNumeros = (totalHours * 10000) + (diffMinutes * 100) + diffSeconds;

    // Formatar o resultado
    const resultado = {
        Dias: diffDays.toString().padStart(2, '0'),
        Horas: `${diffHours.toString().padStart(2, '0')}:${diffMinutes.toString().padStart(2, '0')}:${diffSeconds.toString().padStart(2, '0')}`,
        TotalHoras: `${totalHours.toString().padStart(2, '0')}:${diffMinutes.toString().padStart(2, '0')}:${diffSeconds.toString().padStart(2, '0')}`,
        TotalHorasNumeros: totalHorasNumeros, // Valor numérico sem formatação de string
        Status: isFuture ? 'Futuro' : 'Passado' // Indica se a data está no futuro ou no passado
    };

    // Retornar o resultado
